// nws-img: makes an illustrative AI image for a story and stores it in the public bucket "nws-img".
// POST (x-cron-secret): {prompt, name, model?: 'schnell'|'lucid'|'phoenix', width?, height?, seed?}
//   -> {ok, url, model, bytes}
// The image itself is generated by the Cloudflare worker nws-img (Workers AI, free daily allowance),
// reached with NWS_IMG_URL + NWS_IMG_KEY from app_secrets.
import { createClient } from 'npm:@supabase/supabase-js@2';

const sb = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, { auth: { persistSession: false } });

async function secrets() {
  const { data } = await sb.from('app_secrets').select('k,v').in('k', ['CRON_SECRET', 'NWS_IMG_URL', 'NWS_IMG_KEY']);
  const o: Record<string, string> = {};
  for (const r of data ?? []) o[r.k] = r.v;
  return o;
}

const json = (b: unknown, s = 200) => new Response(JSON.stringify(b), { status: s, headers: { 'content-type': 'application/json' } });

Deno.serve(async (req) => {
  if (req.method !== 'POST') return json({ ok: false, error: 'POST only' }, 405);
  const S = await secrets();
  if (!S.CRON_SECRET || req.headers.get('x-cron-secret') !== S.CRON_SECRET) return json({ ok: false, error: 'unauthorized' }, 401);
  let b: any = {};
  try { b = await req.json(); } catch { return json({ ok: false, error: 'bad json' }, 400); }
  const prompt = String(b.prompt ?? '').trim();
  const name = String(b.name ?? '').replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 80);
  if (!prompt || !name) return json({ ok: false, error: 'prompt and name required' }, 400);
  const r = await fetch(S.NWS_IMG_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'x-key': S.NWS_IMG_KEY },
    body: JSON.stringify({ prompt, model: b.model ?? 'schnell', width: b.width ?? 1280, height: b.height ?? 720, seed: b.seed }),
  });
  if (!r.ok) return json({ ok: false, error: `worker ${r.status}: ${(await r.text()).slice(0, 200)}` }, 502);
  const ct = r.headers.get('content-type') ?? 'image/jpeg';
  const ext = ct.includes('png') ? 'png' : 'jpg';
  const bytes = new Uint8Array(await r.arrayBuffer());
  const path = `${name}.${ext}`;
  const up = await sb.storage.from('nws-img').upload(path, bytes, { contentType: ct, upsert: true, cacheControl: '31536000' });
  if (up.error) return json({ ok: false, error: up.error.message }, 500);
  const url = sb.storage.from('nws-img').getPublicUrl(path).data.publicUrl;
  return json({ ok: true, url, model: r.headers.get('x-model'), bytes: bytes.length });
});
